cd /tmp/main-edit && python3 - <<'PY'
import re, glob
problems=[]
for f in sorted(glob.glob('S0*/*.md')):
    t=open(f,encoding='utf-8').read()
    if not t.startswith('---\n'):
        problems.append((f,'no frontmatter')); continue
    m=re.match(r'^---\n(.*?)\n---\n',t,re.S)
    fm=m.group(1)
    if not re.search(r'^title: "[^"]+"$',fm,re.M): problems.append((f,'bad title'))
    for k in ('season','episode'):
        if not re.search(rf'^{k}: \d+$',fm,re.M): problems.append((f,f'bad {k}'))
    if not re.search(r'^status: (ongoing|complete)$',fm,re.M): problems.append((f,'bad status'))
    blocks=t[m.end():].strip('\n').split('\n\n')
    # first block is summary paragraph
    s=re.search(r'^summary: "(.*)"$',fm,re.M).group(1)
    if blocks[0].strip()!=s: problems.append((f,'summary/intro mismatch'))
    # entries
    shas=re.findall(r'Source: friend/([a-z]+) @ ([0-9a-f]{40})',t)
    heads=re.findall(r'^\*\*([A-Z][a-z]+)\*\* \((\d{4}-\d\d-\d\dT[0-9:]+Z)\)$',t,re.M)
    if len(shas)!=len(heads): problems.append((f,f'sha/head count {len(shas)} vs {len(heads)}'))
    if len(set(x[1] for x in shas))!=len(shas): problems.append((f,'duplicate sha'))
    for (sp,sha),(hn,ts) in zip(shas,heads):
        if sp.lower()!=hn.lower(): problems.append((f,f'name mismatch {sp}/{hn}'))
    times=[h[1] for h in heads]
    if times!=sorted(times): problems.append((f,'timestamps not monotonic'))
print("files:",len(glob.glob('S0*/*.md')),"problems:",len(problems))
for p in problems: print(p)
PY

